-- ==============================================================
-- DB Cargo Belgium — Supabase Database Setup & Initial Seed
-- Voer dit eenmalig uit in de Supabase SQL Editor (https://supabase.com)
-- ==============================================================

-- 1. Maak de locations tabel aan
CREATE TABLE IF NOT EXISTS public.locations (
    id TEXT PRIMARY KEY,
    category TEXT DEFAULT 'bediening',
    name TEXT NOT NULL,
    lat DOUBLE PRECISION NOT NULL,
    lng DOUBLE PRECISION NOT NULL,
    aliases JSONB DEFAULT '[]'::jsonb,
    is_merged BOOLEAN DEFAULT FALSE,
    merged_into TEXT DEFAULT NULL,
    data JSONB DEFAULT '{}'::jsonb,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Schakel Row Level Security (RLS) in en sta veilige anonieme toegang toe
ALTER TABLE public.locations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public Read" ON public.locations;
CREATE POLICY "Public Read" ON public.locations FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Insert" ON public.locations;
CREATE POLICY "Public Insert" ON public.locations FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public Update" ON public.locations;
CREATE POLICY "Public Update" ON public.locations FOR UPDATE USING (true) WITH CHECK (true);

-- 3. Schakel Realtime in voor live synchronisatie tussen collega's
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_publication_tables 
        WHERE pubname = 'supabase_realtime' AND tablename = 'locations'
    ) THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.locations;
    END IF;
END $$;

