-- 5. Optionele trigger om updated_at altijd automatisch bij te werken
CREATE OR REPLACE FUNCTION update_modified_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS set_locations_timestamp ON public.locations;
CREATE TRIGGER set_locations_timestamp
BEFORE UPDATE ON public.locations
FOR EACH ROW
EXECUTE FUNCTION update_modified_column();
